"""Compares the OpenAPI generated by the API with the approved contract (ADR-16, BE-18).

Only what a client depends on is compared: operations, parameters, request bodies, the status
codes and the shape of each response. Wording (titles, descriptions, examples) is ignored, and so
is how the two documents spell the same thing (`anyOf` with null versus a type list, $ref versus
inline).
"""

from typing import Any

Json = dict[str, Any]

# Documentation only: changing them never changes what a client sees.
IGNORED_KEYS = frozenset(
    {
        "title",
        "description",
        "summary",
        "example",
        "examples",
        "externalDocs",
        "x-codeSamples",
        "deprecated",
        # A default only tells what the server fills in; clients depend on the shape.
        "default",
        # Strictness of unknown properties is a validation choice, not part of the shape.
        "additionalProperties",
        "unevaluatedProperties",
    }
)
METHODS = ("get", "put", "post", "delete", "patch")


def _resolve(node: Any, doc: Json) -> Any:
    while isinstance(node, dict) and "$ref" in node:
        target: Any = doc
        for part in node["$ref"].removeprefix("#/").split("/"):
            target = target[part]
        node = target
    return node


def _as_nullable(node: Json, doc: Json) -> Json:
    """`anyOf`/`oneOf: [X, {type: null}]` is the same as X with a nullable type."""
    for choice in ("anyOf", "oneOf"):
        options = node.get(choice)
        if not isinstance(options, list):
            continue
        non_null = [o for o in options if _resolve(o, doc).get("type") != "null"]
        if len(non_null) == 1 and len(non_null) != len(options):
            rest = {k: v for k, v in node.items() if k != choice}
            inner = canon(non_null[0], doc)
            kind = inner.get("type")
            kinds = kind if isinstance(kind, list) else [kind]
            merged = {**inner, **{k: canon(v, doc) for k, v in rest.items()}}
            merged["type"] = sorted({*kinds, "null"})
            return merged
    return node


def canon(node: Any, doc: Json) -> Any:
    """A schema in a form that is the same however each document wrote it."""
    node = _resolve(node, doc)
    if isinstance(node, list):
        return [canon(item, doc) for item in node]
    if not isinstance(node, dict):
        return node
    node = {k: v for k, v in node.items() if k not in IGNORED_KEYS}
    if "allOf" in node and len(node["allOf"]) == 1:
        inner = canon(node.pop("allOf")[0], doc)
        node = {**inner, **{k: canon(v, doc) for k, v in node.items()}}
    nullable = _as_nullable(node, doc)
    if nullable is not node:
        return nullable
    if "const" in node:  # a single-value enum, however it is written
        node = {**{k: v for k, v in node.items() if k != "const"}, "enum": [node["const"]]}
    out: Json = {}
    for key, value in node.items():
        if key == "type" and isinstance(value, list):
            out[key] = sorted(value)
        elif key in ("enum", "required"):
            out[key] = sorted(value, key=str)
        elif key == "properties":
            out[key] = {name: canon(sub, doc) for name, sub in value.items()}
        else:
            out[key] = canon(value, doc)
    return out


def operations(spec: Json) -> dict[str, tuple[str, str, Json]]:
    """operationId -> (method, path, operation)."""
    found: dict[str, tuple[str, str, Json]] = {}
    for path, item in spec.get("paths", {}).items():
        for method in METHODS:
            operation = item.get(method)
            if operation and "operationId" in operation:
                found[operation["operationId"]] = (method, path, operation)
    return found


def _parameters(operation: Json, item: Json, doc: Json) -> dict[tuple[str, str], Any]:
    raw = [*item.get("parameters", []), *operation.get("parameters", [])]
    result: dict[tuple[str, str], Any] = {}
    for parameter in raw:
        p = _resolve(parameter, doc)
        schema = canon(p.get("schema", {}), doc)
        if not p.get("required", False) and isinstance(schema.get("type"), list):
            # An optional query parameter may be left out; FastAPI also writes it as nullable.
            kinds = [k for k in schema["type"] if k != "null"]
            schema = {**schema, "type": kinds[0] if len(kinds) == 1 else kinds}
        result[(p["in"], p["name"])] = (bool(p.get("required", False)), schema)
    return result


def _content(response: Json, doc: Json) -> dict[str, Any]:
    content = _resolve(response, doc).get("content", {})
    return {
        media: canon(body.get("schema", {}), doc) if "json" in media else None
        for media, body in content.items()
    }


def differences(approved: Json, generated: Json, operation_ids: set[str]) -> list[str]:
    """Why the generated operations are not the approved ones. Empty means they match."""
    wanted = operations(approved)
    actual = operations(generated)
    problems: list[str] = []
    for op_id in sorted(operation_ids):
        if op_id not in actual:
            problems.append(f"{op_id}: is not served by the API")
            continue
        a_method, a_path, a_op = wanted[op_id]
        g_method, g_path, g_op = actual[op_id]
        if (a_method, a_path) != (g_method, g_path):
            problems.append(
                f"{op_id}: {g_method.upper()} {g_path} instead of {a_method.upper()} {a_path}"
            )
            continue
        a_item = approved["paths"][a_path]
        g_item = generated["paths"][g_path]
        a_params = _parameters(a_op, a_item, approved)
        g_params = _parameters(g_op, g_item, generated)
        if a_params != g_params:
            problems.append(
                f"{op_id}: parameters differ ({sorted(a_params)} vs {sorted(g_params)})"
            )
        a_body = _body(a_op, approved)
        g_body = _body(g_op, generated)
        if a_body != g_body:
            problems.append(f"{op_id}: request body differs")
        # 422 is FastAPI's automatic answer to a malformed request; the contract does not list it.
        a_codes = set(a_op["responses"]) - {"422"}
        g_codes = set(g_op["responses"]) - {"422"}
        if a_codes != g_codes:
            problems.append(f"{op_id}: status codes {sorted(g_codes)} instead of {sorted(a_codes)}")
        for code in sorted(a_codes & g_codes):
            if _content(a_op["responses"][code], approved) != _content(
                g_op["responses"][code], generated
            ):
                problems.append(f"{op_id}: response {code} differs")
    return problems


def _body(operation: Json, doc: Json) -> Any:
    body = operation.get("requestBody")
    if body is None:
        return None
    resolved = _resolve(body, doc)
    return (bool(resolved.get("required", False)), _content(resolved, doc))
